arguments.new_str:
using ModelContextProtocol;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<ConfigTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Gets a configuration value by key")]
    public static string GetConfigValue(string key)
    {
        var config = new Dictionary<string, string>
        {
            ["app.name"] = "MyService",
            ["app.version"] = "1.0.0",
            ["app.environment"] = "production",
            ["app.maxRetries"] = "3",
        };

        return config.TryGetValue(key, out var value)
            ? value
            : $"Unknown config key: {key}";
    }

    [McpServerTool, Description("Lists all available configuration keys")]
    public static string[] ListConfigKeys()
    {
        return ["app.name", "app.version", "app.environment", "app.maxRetries"];
    }
}

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://settings",
        Name = "Application Settings",
        Description = "Returns the full application configuration as JSON")]
    public static string GetAllSettings()
    {
        return """
        {
            "app.name": "MyService",
            "app.version": "1.0.0",
            "app.environment": "production",
            "app.maxRetries": "3"
        }
        """;
    }

    [McpServerResource(
        UriTemplate = "config://settings/{section}",
        Name = "Configuration Section",
        Description = "Returns configuration for a specific section")]
    public static string GetSection(string section)
    {
        return section switch
        {
            "app" => """{"name": "MyService", "version": "1.0.0"}""",
            "logging" => """{"level": "Information", "format": "json"}""",
            _ => $"""{{ "error": "Unknown section: {section}" }}""",
        };
    }
}

